def dedupe_by_last(records):
    seen = {}
    order = []
    for record in records:
        key = record[0]
        if key not in seen:
            seen[key] = True
            order.append(record)
    result = []
    for key in reversed(seen):
        # Find the last occurrence of this key in the original order
        # by scanning the original records in reverse
        for record in reversed(records):
            if record[0] == key:
                result.append(record)
